GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Greedily minimize resulting KVPR, then relocate models when max KVPR decreases."""
    placement = {gpu_id: [] for gpu_id in range(gpu_num)}
    remaining = [GPU_MEM_SIZE] * gpu_num
    pressure = [0.0] * gpu_num

    for model in sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True):
        weight = model.req_rate / model.slo
        candidates = [
            gpu_id for gpu_id in range(gpu_num)
            if remaining[gpu_id] >= model.model_size
        ]
        if not candidates:
            raise ValueError(
                f"Unable to place model of size {model.model_size} GB; "
                f"remaining memory: {remaining}"
            )
        best_gpu = min(
            candidates,
            key=lambda i: (
                (pressure[i] + weight) / (remaining[i] - model.model_size)
                if remaining[i] > model.model_size else float("inf")
            ),
        )
        placement[best_gpu].append(model)
        remaining[best_gpu] -= model.model_size
        pressure[best_gpu] += weight

    for _ in models:
        ratios = [
            pressure[i] / remaining[i] if remaining[i] else float("inf")
            for i in range(gpu_num)
        ]
        best_value, best_move = max(ratios), None

        for src in range(gpu_num):
            if ratios[src] != best_value:
                continue
            for model in placement[src]:
                weight = model.req_rate / model.slo
                src_value = (
                    (pressure[src] - weight) /
                    (remaining[src] + model.model_size)
                )
                for dst in range(gpu_num):
                    free = remaining[dst] - model.model_size
                    if dst == src or free <= 0:
                        continue
                    dst_value = (pressure[dst] + weight) / free
                    value = max(
                        src_value if i == src else
                        dst_value if i == dst else ratios[i]
                        for i in range(gpu_num)
                    )
                    if value < best_value:
                        best_value = value
                        best_move = src, dst, model, weight

        if best_move is None:
            break
        src, dst, model, weight = best_move
        placement[src].remove(model)
        placement[dst].append(model)
        remaining[src] += model.model_size
        remaining[dst] -= model.model_size
        pressure[src] -= weight
        pressure[dst] += weight

    return placement

